from collections import OrderedDict

class TTLCache:
    def __init__(self, capacity, ttl, clock):
        self.capacity = capacity
        self.ttl = ttl
        self.clock = clock
        self.items = OrderedDict()

    def get(self, key):
        if key not in self.items:
            return None
        value, expires_at = self.items[key]
        if self.clock() > expires_at:
